import{_ as n,C as a,c as r,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Order notes and customers","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/selling/order-notes-and-customers.md","filePath":"master/sales/point-of-sale/selling/order-notes-and-customers.md","lastUpdated":1792041590000}'),l={name:"master/sales/point-of-sale/selling/order-notes-and-customers.md"};function d(c,e,h,u,m,g){const o=a("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="order-notes-and-customers" tabindex="-1">Order notes and customers <a class="header-anchor" href="#order-notes-and-customers" aria-label="Permalink to &quot;Order notes and customers&quot;">​</a></h1><p>Notes tell the kitchen or the team something about a line. A customer on the order lets you invoice it later and keep a sales history. This page shows how to add both.</p><blockquote><p><strong>In simple words:</strong> Use Note for special requests on one product. Use Customer to say who is buying.</p></blockquote><h2 id="add-a-note-to-a-line" tabindex="-1">Add a note to a line <a class="header-anchor" href="#add-a-note-to-a-line" aria-label="Permalink to &quot;Add a note to a line&quot;">​</a></h2><ol><li>Click the line you want to annotate. The <strong>Note</strong> button turns on only when a line is selected.</li><li>Click <strong>Note</strong>. The note window opens.</li></ol>',5)),s(o,{src:"/images1/pos/note_window.png",alt:"Internal note window for Glide Wireless Mouse with quick notes Wait, To Serve, Emergency and No Dressing"}),e[1]||(e[1]=t('<ol start="3"><li>Click a quick note, such as <strong>Wait</strong>, <strong>To Serve</strong>, <strong>Emergency</strong> or <strong>No Dressing</strong>. Or type your own text in the box.</li><li>Click <strong>Apply</strong>. The note shows under the line as a small label.</li></ol>',1)),s(o,{src:"/images1/pos/note_on_line.png",alt:"Order line Mango Lassi with the Wait note label under the price"}),e[2]||(e[2]=t('<p>Click <strong>Clear</strong> to remove the note.</p><p><strong>Example:</strong> At Spice Route, the waiter selects Mango Lassi x2 and clicks the <strong>Wait</strong> quick note. The kitchen sees &quot;Wait&quot; on that line.</p><h3 id="internal-note-and-kitchen-note" tabindex="-1">Internal note and kitchen note <a class="header-anchor" href="#internal-note-and-kitchen-note" aria-label="Permalink to &quot;Internal note and kitchen note&quot;">​</a></h3><p>In a shop the window is titled <strong>Internal note</strong>. In a restaurant it is titled <strong>Kitchen note</strong>, and the note goes with the line to the kitchen.</p><p>The quick notes come from your list of note models. See <a href="./../get-started/set-up-a-register.html">Set up a register</a>.</p><h2 id="add-a-customer" tabindex="-1">Add a customer <a class="header-anchor" href="#add-a-customer" aria-label="Permalink to &quot;Add a customer&quot;">​</a></h2><ol><li>Click <strong>Customer</strong> in the order panel. The <strong>Select a customer</strong> window opens.</li><li>Type in <strong>Search customers</strong> to find a person or company.</li><li>Click the name. The window closes and the button shows the customer&#39;s name.</li></ol>',7)),s(o,{src:"/images1/pos/customer_picker.png",alt:"Select a customer window with the search box and a list of customers including Sofia Rossi"}),e[3]||(e[3]=t('<p>To change the customer, click the name button and pick another. Use <strong>Remove customer</strong> to clear it.</p><h3 id="create-a-customer-at-the-till" tabindex="-1">Create a customer at the till <a class="header-anchor" href="#create-a-customer-at-the-till" aria-label="Permalink to &quot;Create a customer at the till&quot;">​</a></h3><p>Click <strong>New customer</strong> in the window. Fill in <strong>Name</strong>, <strong>Email</strong> and <strong>Phone</strong>. The new customer is added and selected at once.</p><p>Customers are the same contacts used in the rest of Aureus. See <a href="./../../../getting-started/contacts/contacts.html">Contacts</a>.</p><p><strong>Example:</strong> TechNest picks <strong>Sofia Rossi</strong> so the sale can be invoiced to her later.</p><h2 id="customer-required-setting" tabindex="-1">Customer Required setting <a class="header-anchor" href="#customer-required-setting" aria-label="Permalink to &quot;Customer Required setting&quot;">​</a></h2><p>A register can force a customer on every sale.</p><ul><li><strong>Setting:</strong> <code>Point of Sale → Configurations → Point of Sale</code>, open the register, tab <strong>PoS Interface</strong>.</li><li><strong>Option:</strong> <strong>Customer Required</strong>.</li></ul><p>When it is on, validating an order without a customer shows &quot;Customer required&quot;. Some payment methods and the <strong>Invoice</strong> option need a customer too. Pick one, then validate again.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><p>Notes and customers can change while the order is <strong>New</strong>. They are part of the receipt and the order record after payment.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Quick notes are fast. Add the ones your team uses most to your note models.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./take-an-order.html">Take an order</a></li><li><a href="./restaurant-tables.html">Restaurant tables</a></li><li><a href="./invoice-a-pos-order.html">Invoice a POS order</a></li></ul>',14))])}const k=n(l,[["render",d]]);export{_ as __pageData,k as default};
